using System;
using System.Collections.Generic;
using UnityEngine;

namespace Metro.View {
    /// <summary>
    /// Serialized mapping from a stable visual key to the promoted prefab (or to the
    /// named runtime generator) that draws it. Generated by
    /// <c>Metro.Editor.RuntimeCatalogue</c> from <c>unity/asset-recipes/runtime-views.json</c>;
    /// editor paths never appear here, only the prefab references the player build
    /// needs.
    /// </summary>
    [CreateAssetMenu(menuName = "Metro/Runtime Catalogue", fileName = "RuntimeCatalogue")]
    public sealed class RuntimeCatalogue : ScriptableObject, IModuleViewSet {
        public const string AssetPath = "Assets/StationDesigner/Generated/RuntimeCatalogue.asset";

        [Serializable]
        public sealed class Entry {
            public string key = "";
            /// <summary>prefab, generated, live or none.</summary>
            public string kind = "prefab";
            public GameObject prefab;
            public string prefabPath = "";
            public string generator = "";
            public string binding = "";
            public string recipeId = "";
            public string city = "";
            public string part = "";
            public string status = "";
            /// <summary>Source group pivot measured from the cell corner: plan x, plan y, elevation.</summary>
            public Vector3 offset = new Vector3(.5f, .5f, 1);
            public int cells;
            public bool palette;
        }

        public int schemaVersion = 1;
        public Entry[] entries = Array.Empty<Entry>();

        Dictionary<string, Entry> index;

        public int Count => entries?.Length ?? 0;

        public void EnsureIndex() {
            if (index != null && index.Count == Count) return;
            index = new Dictionary<string, Entry>(Count, StringComparer.Ordinal);
            if (entries == null) return;
            foreach (var entry in entries) {
                if (entry == null || string.IsNullOrEmpty(entry.key)) continue;
                index[entry.key] = entry;
            }
        }

        public bool Has(string key) {
            if (string.IsNullOrEmpty(key)) return false;
            EnsureIndex();
            return index.ContainsKey(key);
        }

        public bool TryGet(string key, out Entry entry) {
            entry = null;
            if (string.IsNullOrEmpty(key)) return false;
            EnsureIndex();
            return index.TryGetValue(key, out entry);
        }

        public GameObject Prefab(string key) => TryGet(key, out var entry) ? entry.prefab : null;

        /// <summary>
        /// The promoted road-traffic prefab for a simulation variant
        /// (<c>suv/sedan/bus-orange/bus-mosaic/moped/bicycle</c>), or null when the
        /// catalogue has no row for that variant. A null here is a diagnostic the
        /// renderer reports by key, never a silent stand-in.
        /// </summary>
        public GameObject VehiclePrefab(string variant) =>
            RoadVehicleViewKeys.TryForVariant(variant, out var key) ? Prefab(key) : null;

        public IEnumerable<Entry> Entries => entries ?? Array.Empty<Entry>();

        void OnEnable() => index = null;
    }

    /// <summary>
    /// The road-traffic view keys and their promoted prefabs. The vehicle family is
    /// appended to the generated runtime catalogue by <c>Metro.Editor.RuntimeCatalogue</c>
    /// (the recipe manifest has no <c>station.vehicle.*</c> rows because the six
    /// vehicles are promoted review fixtures, not palette parts). Sim variants come
    /// from <c>game/src/render/models/pieces/RoadVehicleModel.ts</c>.
    /// </summary>
    public static class RoadVehicleViewKeys {
        public const string Suv = "vehicle.suv";
        public const string Sedan = "vehicle.sedan";
        public const string BusOrange = "vehicle.bus-orange";
        public const string BusMosaic = "vehicle.bus-mosaic";
        public const string Moped = "vehicle.moped";
        public const string Bicycle = "vehicle.bicycle";

        /// <summary>Every promoted variant in the source declaration order.</summary>
        public static readonly string[] Variants = { "suv", "sedan", "bus-orange", "bus-mosaic", "moped", "bicycle" };

        /// <summary>The six keys in the same order as <see cref="Variants"/>.</summary>
        public static readonly string[] All = { Suv, Sedan, BusOrange, BusMosaic, Moped, Bicycle };

        public static bool TryForVariant(string variant, out string key) {
            switch (variant) {
                case "suv": key = Suv; return true;
                case "sedan": key = Sedan; return true;
                case "bus-orange": key = BusOrange; return true;
                case "bus-mosaic": key = BusMosaic; return true;
                case "moped": key = Moped; return true;
                case "bicycle": key = Bicycle; return true;
                default: key = ""; return false;
            }
        }

        public static string ForVariant(string variant) => TryForVariant(variant, out var key) ? key : "";

        /// <summary>Stable promoted prefab path for a view key (editor catalogue rows).</summary>
        public static string PrefabPath(string key) {
            switch (key) {
                case Suv: return "Assets/StationDesigner/Generated/Prefabs/VehicleSuv.prefab";
                case Sedan: return "Assets/StationDesigner/Generated/Prefabs/VehicleSedan.prefab";
                case BusOrange: return "Assets/StationDesigner/Generated/Prefabs/VehicleBusOrange.prefab";
                case BusMosaic: return "Assets/StationDesigner/Generated/Prefabs/VehicleBusMosaic.prefab";
                case Moped: return "Assets/StationDesigner/Generated/Prefabs/VehicleMoped.prefab";
                case Bicycle: return "Assets/StationDesigner/Generated/Prefabs/VehicleBicycle.prefab";
                default: return "";
            }
        }

        public static bool IsVehicleKey(string key) => Array.IndexOf(All, key) >= 0;
    }

    /// <summary>A key set the resolver can ask about, so resolver tests need no asset.</summary>
    public interface IModuleViewSet {
        bool Has(string key);
    }

    public sealed class SetViewSet : IModuleViewSet {
        readonly HashSet<string> keys;
        public SetViewSet(IEnumerable<string> keys) => this.keys = new HashSet<string>(keys, StringComparer.Ordinal);
        public bool Has(string key) => keys.Contains(key);
    }
}
